pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz params: amount to send and a boolean that decides whether attacker will reenter
    function testFuzz_property(uint256 amount, bool reenter) public {
        // Keep amount in a reasonable range and non-zero to exercise MinSum / payable
        amount = bound(amount, 1 wei, 10 ether);

        // deploy an attacker that will attempt reentrancy when sending to it
        Attacker attacker = new Attacker(address(c));

        // give attacker funds to send
        vm.deal(address(attacker), amount);

        // record recorded balance before
        uint256 beforeRecorded = c.Acc(address(attacker)).balance;

        // Have attacker call Put with value amount. If reenter==true, attacker will reenter via its receive
        attacker.doPut{value: amount}(reenter, amount);

        // After the single external high-level Put call completes, reference contract guarantees
        // Acc[attacker].balance == beforeRecorded + amount
        // Buggy mutant that allows reentry can make the recorded balance larger (e.g., += amount twice)
        uint256 afterRecorded = c.Acc(address(attacker)).balance;

        assertTrue(afterRecorded == beforeRecorded + amount);
    }
}

// Minimal attacker that may reenter C.Put by calling back in its receive()
contract Attacker {
    C immutable target;
    bool willReenter;
    uint256 reenterAmount;
    bool reentered;

    constructor(address _target) {
        target = C(_target);
    }

    // Called by test to initiate the call from this contract
    function doPut(bool _reenter, uint256 _amt) external payable {
        willReenter = _reenter;
        reenterAmount = _amt;
        reentered = false;
        // call Put on target, sending ETH from this contract's balance
        target.Put{value: _amt}(block.timestamp + 1);
    }

    // receive will attempt to reenter Put exactly once if willReenter is true
    receive() external payable {
        if (willReenter && !reentered) {
            reentered = true;
            // attempt to reenter Put during the same transaction
            // pass a different unlock time (doesn't matter); send 0 value so reentrant execution still runs
            // but it will use msg.value==0; to simulate double-accounting in buggy contract, it's enough
            // that Put executes again (it will add msg.value==0 though). To ensure recorded balance increases
            // again, we call Put with value reenterAmount by forwarding funds: first send them back to this contract
            // and then call Put with value by using selfbalance. Simpler: we just call Put with value 0, but to
            // actually increase recorded balance again we need to send value; therefore perform a call sending reenterAmount
            // from this contract's balance (it has the original funds)
            target.Put{value: reenterAmount}(block.timestamp + 2);
        }
    }
}

