pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: attacker address is not useful (EOA), so fuzz amount and reentrancy toggle via bool
    // amount must be >= 1 wei and >= MinSum to allow Collect path if needed, but we only need Put reentrancy
    function testFuzz_property(uint256 sendAmt, uint256 reentrantCalls) public {
        // keep a reasonable domain: non-zero amount and bounded reentrantCalls
        vm.assume(sendAmt > 0 && sendAmt < type(uint128).max);
        // bound the number of reentrant calls attacker will attempt to a small number
        uint256 tries = uint256(reentrantCalls % 5);

        // deploy attacker that will reenter Put up to 'tries' times
        Attacker attacker = new Attacker(c, tries);

        // fund attacker and call Put via the attacker contract so its fallback can reenter
        vm.deal(address(attacker), sendAmt);

        // attacker initiates Put with all its balance
        bool ok;
        try attacker.attack{value: sendAmt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the external Put returns, the invariant for the reference contract holds:
        // Acc[attacker].balance equals the amount contributed exactly once (sendAmt)
        // Read the public mapping getter: Acc returns (unlockTime, balance) as a tuple
        (uint256 unlock, uint256 recordedBalance) = c.Acc(address(attacker));

        // Exactly one assertion: the reference contract with nonReentrant_ ensures that recordedBalance == sendAmt
        // The mutant that removed the guard can be re-entered and cause recordedBalance > sendAmt for some tries>0
        assertTrue(recordedBalance == sendAmt);
    }
}

// Minimal attacker that tries to reenter Put from its fallback
contract Attacker {
    C public target;
    uint256 public remaining;

    constructor(C _t, uint256 tries) {
        target = _t;
        remaining = tries;
    }

    // entry called by test, sends value and triggers Put via low-level call to target.fallback (Put is public so call to Put)
    function attack() external payable {
        // Call Put on target from this contract so fallback/receive can reenter
        target.Put{value: msg.value}(0);
    }

    // fallback will attempt to reenter Put until remaining is exhausted
    fallback() external payable {
        if (remaining > 0) {
            remaining -= 1;
            // reenter Put during the same transaction
            target.Put{value: 0}(0);
        }
    }
}

