pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz: amount to send, and a boolean choosing whether to use the attacker helper
    function testFuzz_property(uint256 sendAmount, bool useAttacker) public {
        // keep amount reasonable and positive, and within this test's funding
        sendAmount = bound(sendAmount, 1, 10 ether);

        // fund potential attacker/EOA
        address payer = address(0xBEEF);
        vm.deal(payer, 20 ether);

        // record prior stored balance for payer
        uint256 prior = c.Acc(payer).balance();

        // If using attacker, deploy attacker that re-enters Put during receive()
        Attacker attacker;
        address target;
        if (useAttacker) {
            attacker = new Attacker(address(c));
            // fund attacker so it can send ETH when calling Put
            vm.deal(address(attacker), sendAmount);
            target = address(attacker);
            // attacker will call Put on c when we instruct it below
        } else {
            target = payer;
            vm.deal(payer, sendAmount);
        }

        // perform the external call to Put from the chosen caller sending sendAmount
        bool ok;
        if (useAttacker) {
            // attacker initiates a call to c.Put and may reenter
            try attacker.doPut{value: sendAmount}() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(payer);
            try c.Put{value: sendAmount}(block.timestamp + 1) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The universal rule: for the correct contract, the stored balance increased by exactly sendAmount
        // read the stored balance via public getter
        uint256 after = c.Acc(target).balance();

        // single assertion: for the reference (non-reentrant) contract this always holds; the mutant can violate it
        assertTrue((after == prior + sendAmount) == ok);
    }
}

// Minimal attacker that re-enters C.Put in its receive
contract Attacker {
    C public c;
    bool public reentered;

    constructor(address _c) {
        c = C(_c);
        reentered = false;
    }

    // entry to start the attack
    function doPut() external payable {
        // call Put on c; this sends ETH and sets up for reentrancy during any subsequent external call
        c.Put{value: msg.value}(block.timestamp + 1);
    }

    // receive will try to re-enter Put once to emulate a reentrant malicious recipient
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter Put while still in the previous call's context
            c.Put{value: 0}(block.timestamp + 1);
        }
    }
}

