import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz: amount to send, and a boolean selector to choose a reentrant attacker or a normal EOA
    function testFuzz_property(uint128 amt, bool useAttacker) public {
        vm.assume(amt > 0); // need positive ETH to observe effect
        uint256 amount = uint256(amt);

        // fund either the attacker contract or an EOA
        if (useAttacker) {
            // deploy attacker that reenters C.Put during its fallback
            Attacker a = new Attacker(address(c));
            address attacker = address(a);
            vm.deal(attacker, amount);
            // record stored balance before
            uint256 before = c.Acc(attacker).balance();
            // call Put through the attacker which will attempt reentrancy
            a.doPut{value: amount}(amount); // attacker will call Put and reenter
            // after call, check that stored increase is NOT more than msg.value
            uint256 after = c.Acc(attacker).balance();
            // property: after - before <= amount
            assertTrue(after - before <= amount);
        } else {
            // normal EOA caller
            address user = address(0xBEEF);
            vm.deal(user, amount);
            uint256 before = c.Acc(user).balance();
            vm.prank(user);
            c.Put{value: amount}(0);
            uint256 after = c.Acc(user).balance();
            assertTrue(after - before <= amount);
        }
    }
}

// minimal attacker that re-enters C.Put during its fallback to exploit missing nonReentrant_
contract Attacker {
    C public target;
    bool public reentered;
    uint public reenterAmount;
    constructor(address _t) {
        target = C(_t);
    }
    // entry: fund this contract and instruct it to call Put which will trigger fallback reentry
    function doPut(uint _amt) external payable {
        reentered = false;
        reenterAmount = _amt;
        // call Put: this will set up state and then the fallback (or receive) will trigger on any outgoing call
        target.Put{value: msg.value}(0);
    }
    fallback() external payable {
        // attempt a single reentry only once
        if (!reentered && address(this).balance >= reenterAmount) {
            reentered = true;
            // reenter Put to attempt double-increment when nonReentrant_ is missing
            target.Put{value: 0}(0);
        }
    }
}

