pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: unlock time and deposit amount and actor
    function testFuzz_property(uint256 unlockTime, uint256 deposit, address actor) public {
        // keep deposit reasonable and non-zero so MinSum logic doesn't interfere; MinSum is 1 ether in contract
        deposit = bound(deposit, 1 wei, 10 ether);
        // ensure actor is non-zero
        vm.assume(actor != address(0));

        // fund actor so they can send deposit
        vm.deal(actor, deposit);

        // pick a current timestamp and warp to it to make block.timestamp observable
        // keep current time non-zero
        uint256 nowT = bound(block.timestamp, 1, type(uint256).max);
        vm.warp(nowT);

        // perform Put as actor with the fuzzed unlockTime and deposit
        vm.prank(actor);
        c.Put{value: deposit}(unlockTime);

        // Read the stored unlockTime via the public getter for mapping Acc (Acc is public)
        (uint storedUnlockTime, uint storedBalance) = getHolder(actor);

        // The reference contract enforces that storedUnlockTime >= block.timestamp (it uses max with block.timestamp).
        // Mutant sets acc.unlockTime = _unlockTime unconditionally; if unlockTime < block.timestamp, mutant would store a past time < block.timestamp.
        // Assert the universal property: storedUnlockTime >= block.timestamp
        assertTrue(storedUnlockTime >= block.timestamp);
    }

    // helper to read the public mapping Acc: the auto-generated getter for Acc returns (uint unlockTime, uint balance)
    function getHolder(address a) internal view returns (uint, uint) {
        return c.Acc(a);
    }
}

