pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz params: caller address, supplied unlockTime, amount to send
    function testFuzz_property(address caller, uint256 suppliedUnlockTime, uint256 amount) public {
        // keep caller non-zero to be meaningful
        vm.assume(caller != address(0));
        // bound amount to reasonable range so vm.deal works and sums don't overflow
        amount = bound(amount, 0, 10 ether);

        // The reference implementation sets acc.unlockTime = _unlockTime>block.timestamp?_unlockTime:block.timestamp;
        // So the stored value after Put should equal either suppliedUnlockTime if suppliedUnlockTime > block.timestamp,
        // otherwise equal block.timestamp. We will call Put and then read Acc[caller].unlockTime via the public getter.

        // Fund caller so they can send ether in Put
        vm.deal(caller, amount);
        vm.prank(caller);
        // call Put with fuzzed unlockTime and value
        if (amount > 0) {
            // payable call
            c.Put{value: amount}(suppliedUnlockTime);
        } else {
            // also allow zero-value calls
            c.Put(suppliedUnlockTime);
        }

        // read stored unlock time
        (uint storedUnlockTime, ) = getHolder(c, caller);

        // compute expected per reference: max(block.timestamp, suppliedUnlockTime)
        uint expected = suppliedUnlockTime > block.timestamp ? suppliedUnlockTime : block.timestamp;

        // single assertion: reference always satisfies stored == expected; mutant that unconditionally assigns _unlockTime
        // will allow stored < block.timestamp when suppliedUnlockTime < block.timestamp, causing failure for some fuzz input
        assertTrue(storedUnlockTime == expected);
    }

    // helper to read the public struct mapping Acc (auto-generated getter has signature Acc(address) returns (uint unlockTime, uint balance))
    function getHolder(C _c, address who) internal returns (uint, uint) {
        return _c.Acc(who);
    }
}

