        // keep values in wide but sensible ranges
        vm.assume(actor != address(0));
        firstDeposit = bound(firstDeposit, 1 wei, 10 ether);
        secondDeposit = bound(secondDeposit, 1 wei, 10 ether);
        // initialUnlock should be in a wide uint range; we will treat values > block.timestamp as future

        // 1) set actor balance
        vm.deal(actor, firstDeposit + secondDeposit);

