        vm.prank(actor);
        c.Put{value: firstDeposit}(initialUnlock);

        // read stored unlockTime after first Put
        uint256 storedAfterFirst = c.Acc(actor).unlockTime;

        // ensure storedAfterFirst equals max(initialUnlock, block.timestamp) as the reference ensures
