        c.Put{value: secondDeposit}(0);

        // read stored unlockTime after second Put
        uint256 storedAfterSecond = c.Acc(actor).unlockTime;

        // GENERAL RULE (single assert): the unlockTime must not decrease after a subsequent Put
        // i.e., storedAfterSecond >= storedAfterFirst for all inputs on the correct contract
        assertTrue(storedAfterSecond >= storedAfterFirst);
    }
