    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor address and two unlock times
    function testFuzz_property(address actor, uint256 oldUnlock, uint256 newUnlock) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound unlock times to reasonable ranges to avoid overflow in block.timestamp comparisons
        uint256 T0 = bound(oldUnlock, block.timestamp + 1, type(uint256).max);
        uint256 T1 = bound(newUnlock, T0, type(uint256).max); // ensure newUnlock >= oldUnlock

        // 1) actor sets an initial future unlockTime by calling Put with value 0 and oldUnlock (we simulate depositing 1 wei)
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.Put{value: 1 wei}(T0);

        // record stored unlockTime after initial Put
        uint256 storedAfterInitial = c.Acc(actor).unlockTime;

        // ensure initial achieved a future unlockTime as intended
        vm.assume(storedAfterInitial >= T0 && storedAfterInitial > block.timestamp);

        // 2) actor calls Put again with newUnlock >= oldUnlock
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.Put{value: 1 wei}(T1);

        // 3) Assert the invariant: stored unlockTime did not decrease when calling Put with newUnlock >= previous future unlockTime
        uint256 storedAfterSecond = c.Acc(actor).unlockTime;

        // For the reference contract this holds for all inputs; the mutant that always resets to block.timestamp will violate this for some inputs
        assertTrue(storedAfterSecond == storedAfterInitial);
    }
}

