// adversarial helper: always revert on any receive/call to simulate failing low-level call
contract Reverter {
    // allow registering on C by calling Put
    function registerOnC(address caddr, uint256 unlockTime) public payable {
        C(caddr).Put{value: msg.value}(unlockTime);
    }

    receive() external payable {
        revert("no receive");
    }
    fallback() external payable {
        revert("no fallback");
    }

    // attempt to call Collect on c; returns true if call did not revert (i.e., Collect finished without bubbling revert)
    function tryCollect(address caddr, uint256 am) public returns (bool) {
        try C(caddr).Collect(am) {
            return true;
        } catch {
            return false;
        }
    }
}

